	allegiance = "Horda",
	aliases = { "Runthak" },
	sections = {
		{
			title = "Resumen",
			text = [=[El señor supremo Runthak cumple las órdenes del Jefe de Guerra sin cuestionarlas. Lo dice él mismo, y está orgulloso de ello. Mantiene el orden en el {link:valley-of-strength}Valley of Strength{/link} y vigila a sus multitudes. Cuando un héroe de la {link:horde}Horda{/link} regresa con la cabeza de un gran enemigo, es Runthak quien llama a la ciudad a contemplarla.]=],
