		},
	},
	mentions = {
		{ text = "Para que todos lo vean" },
		{ text = "El viaje acaba de comenzar" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "su Jefe de Guerra" },
	},
})

