	allegiance = "Trols de Lanza Negra",
	sections = {
		{
			title = "Resumen",
			text = [=[Kor'ghan es un trol de los {link:darkspear-trolls}Lanza Negra{/link} que trabaja en el {link:cleft-of-shadow}Cleft of Shadow{/link}. Conoce los venenos de los escórpidos de {link:durotar}Durotar{/link}, y cómo convertir el veneno de un escórpido en su cura. También es un severo maestro de rituales, y quienes aprenden de él deben demostrar su valía una y otra vez. Sus discípulos se quejan, pero viven.]=],
		},
